function je_news_article(string $slug): ?array
{
    $articles = je_news_articles();
    if (!isset($articles[$slug])) {
        return null;
    }

    return array_merge([
        'title' => '',
        'date' => '',
        'category' => 'Technology News',
        'description' => '',
        'intro' => '',
        'sections' => [],
        'source_name' => '',
        'source_url' => '',
        'sources' => [],
    ], $articles[$slug]);
